  "setLabel": "Set 1",
  "title": "Describe an exciting sports event you watched.",
  "cues": [
   "what the event was",
   "when and where you watched it",
   "who you watched it with",
   "and explain why it was so exciting for you."
  ],
  "notes": [
   {
    "label": "Intro (0–15 s)",
    "text": "Premier12 baseball final, Taiwan vs Japan – Nov 24, 2024 – played at Tokyo Dome – watched at a packed sports bar in Taipei w/ college friends"
   },
   {
    "label": "Context & description (15–45 s)",
    "text": "no one expected us to win: Japan = 27 int’l wins in a row + home field; Lin Yu-min 4 scoreless innings; 5th inning: Lin Chia-cheng solo HR → captain Chen Chieh-hsien 3-run HR → 4–0"
   },
   {
    "label": "Story (45–75 s)",
    "text": "whole bar jumped up, strangers hugging, pitcher of beer knocked over; last out → people in tears, singing; scooters honking all over the city"
   },
   {
    "label": "Reflection (75–120 s)",
    "text": "Taiwan’s first Premier12 title, beat the best team on their home field; goosebumps; brought young + old together; more friends now go to CPBL games → boost for baseball"
   }
  ],
  "sample": [
   "**Okay, so** the most exciting sports event I’ve ever watched was the final of the Premier12 baseball tournament between Taiwan and Japan on November 24th, 2024. The game was played at the Tokyo Dome, **but** I watched it at a packed sports bar in Taipei with a group of college friends.",
   "**To give you some background,** nobody really expected us to win. Japan had won twenty-seven international games in a row, **and** they were playing at home. **But** our starting pitcher, Lin Yu-min, kept them scoreless for four innings. **Then, in the fifth inning,** Lin Chia-cheng hit a solo home run, and a few minutes later our captain, Chen Chieh-hsien, smashed a three-run homer over the center-field wall. **Suddenly,** it was four to nothing.",
   "**I’ll never forget what happened next.** The whole bar jumped up at the same time. Strangers were hugging each other, someone knocked over a whole pitcher of beer, and nobody even cared. **When the last out was made,** a few people around me were actually in tears, and everyone started singing. **On the way home,** we could hear scooters honking all over the city.",
   "**The reason it was so exciting for me is that** it was Taiwan’s first Premier12 title, and we beat the strongest team in the world on their home field. I had goosebumps the whole evening. **What I loved most** was how it brought everyone together: young and old, even people who normally don’t watch baseball. **Since then,** a lot more of my friends have started going to CPBL games, **so** I think that win gave baseball in Taiwan a real boost."
  ],
  "followUps": [
   {
    "q": "Do you prefer watching sports live or on TV? Why?",
    "a": "**Honestly, I prefer watching live,** at least for baseball. The atmosphere is amazing: the cheerleaders, the drums, everyone singing the players’ songs. **On the other hand,** watching on TV is cheaper, and you get replays and close-ups, **so** you actually see more of the game. **So I’d say** live is for the experience, **while** TV is for really following the game."
   },
   {
    "q": "Why do people get so emotional when their national team wins?",
    "a": "**I think it’s because** it feels personal. The players represent all of us, **so** when they win, it’s like the whole country wins. **For a small place like Taiwan,** international wins mean even more, **because** they show the world what we can do. **That’s why** people who don’t even like sports end up crying in front of the TV."
   },
   {
    "q": "Should governments spend money on professional sports?",
    "a": "**To some extent, yes.** Sports can unite people and inspire kids to be more active. **But** I think the money should go to the grassroots first, like better school sports facilities and coaches, **rather than** only to star athletes. **After all,** today’s young players are tomorrow’s national team."
   }
  ]
